//! Golden parity: Rust `Atr`/`Cmo` (Decimal) vs the Python `tantra_library` kernel.
//!
//! Fixture `golden/atr_cmo_tantra_library.json` is generated by the Python kernel
//! (ATR(14), CMO(9), Decimal prec 28). Comparison is at `round_dp(20)`:
//! Python's context keeps 28 significant digits while `rust_decimal` keeps 28 decimal places,
//! so results below 10 in magnitude differ only in digits beyond the 26th significant place
//! (e.g. CMO -1.2345679012345679012345679012 vs ...901).

use rust_decimal::Decimal;
use std::str::FromStr;
use tantra_market_indicators::{Atr, Cmo, Indicator};

fn dec(v: &serde_json::Value) -> Decimal {
    Decimal::from_str(v.as_str().expect("string")).expect("decimal")
}

fn r20(d: Decimal) -> Decimal {
    d.round_dp(20)
}

fn opt(v: &serde_json::Value) -> Option<Decimal> {
    if v.is_null() { None } else { Some(dec(v)) }
}

#[test]
fn atr14_and_cmo9_match_tantra_library_golden_vectors() {
    let doc: serde_json::Value =
        serde_json::from_str(include_str!("golden/atr_cmo_tantra_library.json")).expect("json");
    let rows = doc["rows"].as_array().expect("rows");
    assert_eq!(rows.len(), 80);
    let mut atr = Atr::new(14);
    let mut cmo = Cmo::new(9);
    let mut warm_atr = 0;
    let mut warm_cmo = 0;
    for (i, r) in rows.iter().enumerate() {
        let a = atr.update_hlc(dec(&r["high"]), dec(&r["low"]), dec(&r["close"]));
        let m = cmo.update(dec(&r["close"]));
        assert_eq!(a.map(r20), opt(&r["atr14"]).map(r20), "atr14 row {i}");
        assert_eq!(m.map(r20), opt(&r["cmo9"]).map(r20), "cmo9 row {i}");
        warm_atr += usize::from(a.is_some());
        warm_cmo += usize::from(m.is_some());
    }
    assert_eq!(warm_atr, 80 - 13);
    assert_eq!(warm_cmo, 80 - 9);
}
